                    _cache = [];
                    _isDirty = false;
                    Logger.LogDebugWarning($"Cleaning factory to type: '{typeof(T).FullOrName()}'");
                }
                foreach (var kv in _instances)
                    if (kv.Value is IDisposable i) i.Dispose();

                _instances.Clear();
            }
        }
